from models import get_db

bp = Blueprint('api', __name__)

# Helper to convert sqlite row to dict
def row_to_dict(row):
    return {key: row[key] for key in row.keys()}

# UI placeholder routes (non-API) returning simple success JSON
@bp.route('/home', methods=['GET'])
def home():
    return jsonify({"success": True})

@bp.route('/periods', methods=['GET'])
def periods():
    return jsonify({"success": True})

@bp.route('/periods/new', methods=['GET'])
def periods_new():
    return jsonify({"success": True})

@bp.route('/periods/<int:item_id>', methods=['GET'])
def periods_detail(item_id):
    return jsonify({"success": True})

@bp.route('/dashboard', methods=['GET'])
def dashboard():
    return jsonify({"success": True})

@bp.route('/settings', methods=['GET'])
def settings():
    return jsonify({"success": True})

# ----- PeriodLog API -----
@bp.route('/api/periodlogs', methods=['GET'])
def get_periodlogs():
    db = get_db()
    cur = db.execute('SELECT id, start_date, end_date, flow, symptoms, notes FROM periodlog')
    rows = cur.fetchall()
    data = [row_to_dict(row) for row in rows]
    return jsonify({"success": True, "data": data})

@bp.route('/api/periodlogs', methods=['POST'])
def create_periodlog():
    payload = request.get_json() or {}
    required_fields = ['start_date', 'end_date', 'flow', 'symptoms', 'notes']
    if not all(field in payload for field in required_fields):
        return jsonify({"success": False, "error": "Missing fields"}), 400
    db = get_db()
    cur = db.execute(
        'INSERT INTO periodlog (start_date, end_date, flow, symptoms, notes) VALUES (?, ?, ?, ?, ?)',
        (payload['start_date'], payload['end_date'], payload['flow'], payload['symptoms'], payload['notes'])
    )
    db.commit()
    new_id = cur.lastrowid
    return jsonify({"success": True, "data": {"id": new_id}}), 201

@bp.route('/api/periodlogs/<int:item_id>', methods=['GET'])
def get_periodlog(item_id):
    db = get_db()
    cur = db.execute(
        'SELECT id, start_date, end_date, flow, symptoms, notes FROM periodlog WHERE id = ?',
        (item_id,)
    )
    row = cur.fetchone()
    if row is None:
        return jsonify({"success": False, "error": "Not found"}), 404
    return jsonify({"success": True, "data": row_to_dict(row)})

